package org.demo.orderservice.privacy;

import org.demo.platformsecurity.privacy.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;
import static org.demo.platformsecurity.privacy.CommerceRetentionAssessment.*;
import static org.demo.orderservice.privacy.CommerceRetentionHoldRestorationPreparation.*;
import org.demo.orderservice.privacy.CommerceRetentionHoldRestorationProgress.Code;
import static org.demo.orderservice.privacy.CommerceRetentionHoldRestorationProgress.*;

import org.demo.orderservice.privacy.CommerceRetentionHoldRepairAssessment.State;
import java.time.Instant;

@Testcontainers
class CommerceRetentionHoldRestorationProgressPostgresIT {
    @Container static final PostgreSQLContainer<?> DB=new PostgreSQLContainer<>("postgres:16-alpine").withDatabaseName("hold_restoration_preparation").withUsername("fixture").withPassword("fixture-only");
    static DriverManagerDataSource ds;static JdbcTemplate jdbc;static DataSourceTransactionManager manager;
    CommerceRetentionHoldRestorationPreparation preparation;CommerceRetentionHoldRecoveryPlanning planning;CommerceRetentionHoldRepairAssessment assessment;CommerceRetentionHoldReconciliationHistory history;CommerceRetentionHoldDelivery sender;CommerceRetentionHoldIntake.Registration intake;
    @BeforeAll static void initialize(){ds=new DriverManagerDataSource(DB.getJdbcUrl(),DB.getUsername(),DB.getPassword());jdbc=new JdbcTemplate(ds);manager=new DataSourceTransactionManager(ds);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();}
    @BeforeEach void reset(){
        jdbc.execute("TRUNCATE orders,commerce_retention_holds,commerce_retention_hold_scopes RESTART IDENTITY CASCADE");
        jdbc.update("INSERT INTO orders(id,customer_id,customer_email,total_price,status,delivery_first_name,delivery_last_name,delivery_street,delivery_postal_code,delivery_city,delivery_country,delivery_phone,delivery_method,delivery_cost,discount_amount,fulfillment_type,idempotency_key,checkout_request_hash,checkout_principal,created_at,updated_at) VALUES(10,17,'fixture@example.test',10,'CANCELLED','Fixture','Buyer','Street','00-001','City','PL','123','COURIER',0,0,'HOME_DELIVERY','fixture-10',?,'fixture',now(),now())","a".repeat(64));
        intake=new CommerceRetentionHoldIntake(ds,manager).register(10,UUID.randomUUID(),UUID.randomUUID(),Guard.NO_PRESERVATION_HOLD,CommerceRetentionHolds.Reason.PRESERVATION_REQUEST);
        preparation=new CommerceRetentionHoldRestorationPreparation(ds,manager);planning=new CommerceRetentionHoldRecoveryPlanning(ds,manager);assessment=new CommerceRetentionHoldRepairAssessment(ds,manager);history=new CommerceRetentionHoldReconciliationHistory(ds,manager);sender=new CommerceRetentionHoldDelivery(ds,manager);
        for(var p:CommerceRetentionSourceHolds.SOURCES)sender.deliver(10,intake.requestId(),intake.caseReference(),p,c->new SourceHoldDeliveryProtocol.Reply(c,SourceHoldDeliveryProtocol.Code.RECORDED,UUID.randomUUID()));
    }
    UUID put(Participant p,CommerceRetentionHoldReconciliation.Code code,Instant time){
        int n=jdbc.queryForObject("SELECT count(*)+1 FROM commerce_retention_hold_probes WHERE request_id=? AND source=?",Integer.class,intake.requestId(),p.name());UUID probe=UUID.randomUUID();
        jdbc.update("INSERT INTO commerce_retention_hold_probes(request_id,source,probe_no,probe_id,source_request_id,source_hold_id) SELECT request_id,source,?,?,source_request_id,source_hold_id FROM commerce_retention_hold_delivery_receipts WHERE request_id=? AND source=?",n,probe,intake.requestId(),p.name());
        if(code!=null){boolean observed=Set.of(CommerceRetentionHoldReconciliation.Code.MATCH_AS_OF_READ,CommerceRetentionHoldReconciliation.Code.MISSING_AT_SOURCE,CommerceRetentionHoldReconciliation.Code.SOURCE_CONFLICT,CommerceRetentionHoldReconciliation.Code.SOURCE_UNKNOWN,CommerceRetentionHoldReconciliation.Code.SOURCE_QUARANTINED).contains(code);boolean versioned=observed && code!=CommerceRetentionHoldReconciliation.Code.SOURCE_UNKNOWN;
            jdbc.update("INSERT INTO commerce_retention_hold_probe_results(probe_id,code,observed_at,binding_epoch,source_revision) VALUES(?,?,?,?,?)",probe,code.name(),observed?java.sql.Timestamp.from(time):null,versioned?2:0,versioned?3:0);
        }return probe;
    }
    UUID intent(Participant source){put(source,CommerceRetentionHoldReconciliation.Code.MISSING_AT_SOURCE,Instant.now());UUID id=UUID.randomUUID();assertThat(planning.prepare(10,intake.requestId(),intake.caseReference(),source,id).code()).isEqualTo(CommerceRetentionHoldRecoveryPlanning.Code.PREPARED);return id;}
    Prepared prepare(Participant source,UUID intent,SourceHoldRestorationProtocol.Mode mode){return preparation.prepare(10,intake.requestId(),intake.caseReference(),source,intent,UUID.randomUUID(),"fixture-sensitive-authorization",mode);}

    CommerceRetentionHoldRestorationDispatch dispatch(){return new CommerceRetentionHoldRestorationDispatch(ds,manager,RestorationCaseFixture.verifier());}
    SourceHoldRestorationProtocol.Command command(Participant p,UUID id){return RestorationCaseFixture.authorize(preparation.prepare(10,intake.requestId(),intake.caseReference(),p,id,UUID.randomUUID(),"",SourceHoldRestorationProtocol.Mode.RESTORE).command());}
    CommerceRetentionHoldRestorationDispatch.Result step(SourceHoldRestorationProtocol.Command c,CommerceRetentionHoldRestorationDispatch.Transport remote){return dispatch().step(10,intake.requestId(),intake.caseReference(),c.delivery().source(),c.intentId(),c.challenge(),c.mode(),c.authorization(),remote);}
    SourceHoldRestorationProtocol.Reply success(SourceHoldRestorationProtocol.Command c){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return SourceHoldRestorationProtocol.reply(c,c.mode()==SourceHoldRestorationProtocol.Mode.RESTORE?SourceHoldRestorationProtocol.Code.RESTORED:SourceHoldRestorationProtocol.Code.REPLAYED,c.bindingEpoch(),c.sourceRevision()+1,RestorationCaseFixture.verifier().verify(c).id());}


    static void awaitReviewClock(UUID intent){
        long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);
        while(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT clock_timestamp()>GREATEST(i.created_at,COALESCE((SELECT max(created_at) FROM commerce_retention_hold_restoration_attempts WHERE intent_id=i.intent_id),'epoch'::timestamptz),COALESCE((SELECT max(r.recorded_at) FROM commerce_retention_hold_restoration_results r JOIN commerce_retention_hold_restoration_attempts a USING(attempt_id) WHERE a.intent_id=i.intent_id),'epoch'::timestamptz))+interval '20 milliseconds' FROM commerce_retention_hold_repair_intents i WHERE i.intent_id=?",Boolean.class,intent))){
            assertThat(System.nanoTime()).as("Fixture database clock must pass prior repair metadata").isLessThan(deadline);
            try{Thread.sleep(2);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new AssertionError(interrupted);}
        }
    }
    CommerceRetentionHoldRestorationProgress progress(){return new CommerceRetentionHoldRestorationProgress(ds,manager);}
    Progress assess(UUID id){return progress().assess(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,id);}
    Refresh refresh(Participant source,UUID id,UUID probe,CommerceRetentionHoldReconciliation.Transport remote){awaitReviewClock(id);return progress().refresh(10,intake.requestId(),intake.caseReference(),source,id,probe,remote);}
    SourceHoldInspectionProtocol.Reply match(SourceHoldInspectionProtocol.Command c){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();return new SourceHoldInspectionProtocol.Reply(c,SourceHoldInspectionProtocol.Code.MATCH,Instant.now(),2,4);}
    UUID acknowledged(Participant source){UUID id=intent(source);assertThat(step(command(source,id),this::success).outcome()).isEqualTo("RESTORED");return id;}
    @ParameterizedTest @EnumSource(value=Participant.class,names={"ORDER"},mode=EnumSource.Mode.EXCLUDE)
    void historyAndFreshMatchAreIndependentAndNeverGrantAuthority(Participant source){
        UUID id=acknowledged(source);UUID probe=UUID.randomUUID();var r=refresh(source,id,probe,c->{assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_hold_probes WHERE probe_id=?",Integer.class,c.challenge())).isEqualTo(1);return match(c);});var p=r.progress();assertThat(p.code()).isEqualTo(Code.ASSESSED);assertThat(p.delivery()).isEqualTo(Delivery.HISTORICAL_ACKNOWLEDGEMENT);assertThat(p.inspection()).isEqualTo(Inspection.MATCH_AS_OF_READ);assertThat(p.latestProbeId()).isEqualTo(probe);assertThat(p.probesUsed()).isEqualTo(2);assertThat(p.remainingProbes()).isEqualTo(6);assertThat(p.historicalAcknowledgements()).isEqualTo(1);assertThat(p.pendingAttempts()).isZero();assertThat(p.currentAuthority()).isFalse();assertThat(p.executionTerminated()).isFalse();assertThat(p.repairExecutionAllowed()).isFalse();assertThat(p.completeCaseCoverage()).isFalse();assertThat(p.activationAllowed()).isFalse();assertThat(refresh(source,id,probe,c->{throw new AssertionError();}).progress().latestProbeId()).isEqualTo(probe);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_hold_restoration_results",Integer.class)).isEqualTo(1);
    }
    @Test void matchDoesNotAcknowledgeUnknownWriteAndLaterReplayDoesNotRewritePending(){
        UUID id=intent(Participant.PAYMENT);var c=command(Participant.PAYMENT,id);step(c,x->{throw new IllegalStateException();});var p=refresh(Participant.PAYMENT,id,UUID.randomUUID(),this::match).progress();assertThat(p.delivery()).isEqualTo(Delivery.OUTCOME_UNKNOWN);assertThat(p.pendingAttempts()).isEqualTo(1);assertThat(p.inspection()).isEqualTo(Inspection.MATCH_AS_OF_READ);step(RestorationCaseFixture.retry(c,SourceHoldRestorationProtocol.Mode.REPLAY_ONLY),this::success);assertThat(assess(id).inspection()).isEqualTo(Inspection.OLDER_THAN_REPAIR);p=refresh(Participant.PAYMENT,id,UUID.randomUUID(),this::match).progress();assertThat(p.delivery()).isEqualTo(Delivery.HISTORICAL_ACKNOWLEDGEMENT);assertThat(p.pendingAttempts()).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM commerce_retention_hold_restoration_results",Integer.class)).isEqualTo(1);
    }
    @Test void basisObservationCannotCountAsPostRepairInspection(){UUID id=acknowledged(Participant.PAYMENT);var p=assess(id);assertThat(p.inspection()).isEqualTo(Inspection.OLDER_THAN_REPAIR);assertThat(p.probesUsed()).isEqualTo(1);}
    @ParameterizedTest @ValueSource(strings={"MISSING_HOLD","CONFLICT","UNKNOWN_PURCHASE","QUARANTINED","epoch","revision"})
    void sourceDiscrepancyAndVersionMismatchRemainDiagnostic(String variant){
        UUID id=acknowledged(Participant.PAYMENT);var p=refresh(Participant.PAYMENT,id,UUID.randomUUID(),c->new SourceHoldInspectionProtocol.Reply(c,variant.equals("epoch")||variant.equals("revision")?SourceHoldInspectionProtocol.Code.MATCH:SourceHoldInspectionProtocol.Code.valueOf(variant),Instant.now(),variant.equals("UNKNOWN_PURCHASE")?0:variant.equals("epoch")?3:2,variant.equals("UNKNOWN_PURCHASE")?0:variant.equals("revision")?3:4)).progress();assertThat(p.delivery()).isEqualTo(Delivery.HISTORICAL_ACKNOWLEDGEMENT);assertThat(p.inspection()).isEqualTo(switch(variant){case "MISSING_HOLD"->Inspection.MISSING_AT_SOURCE;case "CONFLICT"->Inspection.CONFLICT_REVIEW;case "UNKNOWN_PURCHASE"->Inspection.UNKNOWN_PURCHASE;case "QUARANTINED"->Inspection.SOURCE_QUARANTINED;default->Inspection.VERSION_CHANGED;});assertThat(p.repairExecutionAllowed()).isFalse();
    }
    @Test void staleLatestProbeDoesNotFallBackToOlderMatch(){UUID id=acknowledged(Participant.PAYMENT);refresh(Participant.PAYMENT,id,UUID.randomUUID(),this::match);put(Participant.PAYMENT,CommerceRetentionHoldReconciliation.Code.MATCH_AS_OF_READ,Instant.now().minusSeconds(60));assertThat(assess(id).inspection()).isEqualTo(Inspection.STALE);}
    @Test void pendingLatestProbeDoesNotFallBackAndIsNeverRedispatched(){UUID id=acknowledged(Participant.PAYMENT);refresh(Participant.PAYMENT,id,UUID.randomUUID(),this::match);UUID probe=put(Participant.PAYMENT,null,null);var p=refresh(Participant.PAYMENT,id,probe,c->{throw new AssertionError();}).progress();assertThat(p.inspection()).isEqualTo(Inspection.PENDING);assertThat(p.pendingProbes()).isEqualTo(1);}
    @Test void expiredResponseAndWrongChallengeAreUnavailableNotMissing(){UUID id=acknowledged(Participant.PAYMENT);var r=refresh(Participant.PAYMENT,id,UUID.randomUUID(),c->new SourceHoldInspectionProtocol.Reply(c,SourceHoldInspectionProtocol.Code.MATCH,Instant.now().minusSeconds(60),2,4));assertThat(r.progress().inspection()).isEqualTo(Inspection.UNAVAILABLE);r=refresh(Participant.PAYMENT,id,UUID.randomUUID(),c->new SourceHoldInspectionProtocol.Reply(new SourceHoldInspectionProtocol.Command(c.delivery(),c.expectedHoldId(),UUID.randomUUID()),SourceHoldInspectionProtocol.Code.MATCH,Instant.now(),2,4));assertThat(r.progress().inspection()).isEqualTo(Inspection.UNAVAILABLE);}
    @ParameterizedTest @ValueSource(strings={"parent","order-scope","customer-scope","order-state","stop"})
    void quarantineAndStopPreserveCountersAndNeverStartInspection(String change){
        UUID id=acknowledged(Participant.PAYMENT);if(change.equals("stop"))dispatch().stop(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,id,UUID.randomUUID());else if(change.equals("parent"))jdbc.update("UPDATE commerce_retention_hold_requests SET restore_blocked=TRUE");else if(change.equals("order-scope"))jdbc.update("UPDATE commerce_retention_hold_scopes SET restore_blocked=TRUE");else if(change.equals("customer-scope"))jdbc.update("INSERT INTO commerce_retention_hold_scopes(scope_type,subject_id,restore_blocked) VALUES('CUSTOMER',17,TRUE)");else jdbc.update("INSERT INTO commerce_retention_order_state(order_id,restore_blocked) VALUES(10,TRUE)");var r=refresh(Participant.PAYMENT,id,UUID.randomUUID(),c->{throw new AssertionError();});assertThat(r.probe()).isNull();assertThat(r.progress().code()).isEqualTo(change.equals("stop")?Code.STOPPED:Code.QUARANTINED);assertThat(r.progress().inspection()).isEqualTo(Inspection.BLOCKED);assertThat(r.progress().attemptsUsed()).isEqualTo(1);assertThat(r.progress().probesUsed()).isEqualTo(1);
    }
    @ParameterizedTest @ValueSource(strings={"order","request","case","source","intent"})
    void wrongScopeCannotExposeProgressOrProbe(String change){UUID id=acknowledged(Participant.PAYMENT);long order=change.equals("order")?11:10;var request=change.equals("request")?UUID.randomUUID():intake.requestId();var ref=change.equals("case")?UUID.randomUUID():intake.caseReference();var source=change.equals("source")?Participant.RETURNS:Participant.PAYMENT;var target=change.equals("intent")?UUID.randomUUID():id;var r=progress().refresh(order,request,ref,source,target,UUID.randomUUID(),c->{throw new AssertionError();});assertThat(r.probe()).isNull();assertThat(r.progress().code()).isEqualTo(Code.UNKNOWN_INTENT);assertThat(r.progress().attemptsUsed()).isZero();}
    @Test void existingEightProbeBudgetIsNotResetByProgress(){UUID id=acknowledged(Participant.PAYMENT);for(int i=2;i<=8;i++)refresh(Participant.PAYMENT,id,UUID.randomUUID(),this::match);var r=refresh(Participant.PAYMENT,id,UUID.randomUUID(),c->{throw new AssertionError();});assertThat(r.probe().code()).isEqualTo(CommerceRetentionHoldReconciliationHistory.Code.LIMIT_REACHED);assertThat(r.progress().probesUsed()).isEqualTo(8);assertThat(r.progress().remainingProbes()).isZero();assertThat(r.progress().inspection()).isEqualTo(Inspection.MATCH_AS_OF_READ);}
    @Test void supersededReadRemainsUnknownAndCountedWithoutReset(){UUID id=acknowledged(Participant.PAYMENT);UUID pending=put(Participant.PAYMENT,null,null);UUID replacement=put(Participant.PAYMENT,CommerceRetentionHoldReconciliation.Code.MATCH_AS_OF_READ,Instant.now());assertThat(planning.supersede(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,pending,replacement,UUID.randomUUID()).code()).isEqualTo(CommerceRetentionHoldRecoveryPlanning.Code.RECORDED);var p=assess(id);assertThat(p.supersededProbes()).isEqualTo(1);assertThat(p.pendingProbes()).isZero();assertThat(p.probesUsed()).isEqualTo(3);}
    @Test void callerTransactionsAreRejectedBeforeAnyRpc(){UUID id=acknowledged(Participant.PAYMENT);new TransactionTemplate(manager).executeWithoutResult(tx->{assertThatThrownBy(()->assess(id)).hasMessage("RETENTION_HOLD_RESTORATION_PROGRESS_CALLER_TRANSACTION");assertThatThrownBy(()->refresh(Participant.PAYMENT,id,UUID.randomUUID(),this::match)).isInstanceOf(IllegalStateException.class);});}
    @Test void noAttemptAndNegativeDeliveryAreNotSuccessfulRepair(){UUID id=intent(Participant.PAYMENT);assertThat(assess(id).delivery()).isEqualTo(Delivery.NOT_ATTEMPTED);var c=command(Participant.PAYMENT,id);step(c,x->SourceHoldRestorationProtocol.reply(x,SourceHoldRestorationProtocol.Code.STALE_SOURCE,0,0,null));assertThat(assess(id).delivery()).isEqualTo(Delivery.DIAGNOSTIC_ONLY);assertThat(assess(id).historicalAcknowledgements()).isZero();}
    @Test void corruptCommandScopeFailsClosed(){UUID id=acknowledged(Participant.PAYMENT);jdbc.execute("ALTER TABLE commerce_retention_hold_restoration_attempts DISABLE TRIGGER USER");try{jdbc.update("UPDATE commerce_retention_hold_restoration_attempts SET scope_hash=repeat('b',64)");}finally{jdbc.execute("ALTER TABLE commerce_retention_hold_restoration_attempts ENABLE TRIGGER USER");}assertThat(assess(id).code()).isEqualTo(Code.INCONSISTENT_HISTORY);}
    @Test void sqlFailureReturnsEmptyUnavailableWithoutRpc(){var unavailable=org.mockito.Mockito.mock(javax.sql.DataSource.class);try{org.mockito.Mockito.when(unavailable.getConnection()).thenThrow(new java.sql.SQLException("fixture-private"));}catch(java.sql.SQLException impossible){throw new AssertionError(impossible);}var r=new CommerceRetentionHoldRestorationProgress(unavailable,new DataSourceTransactionManager(unavailable)).refresh(10,intake.requestId(),intake.caseReference(),Participant.PAYMENT,UUID.randomUUID(),UUID.randomUUID(),c->{throw new AssertionError();});assertThat(r.progress().code()).isEqualTo(Code.UNAVAILABLE);assertThat(r.progress().attemptsUsed()).isZero();assertThat(r.probe()).isNull();assertThat(r.toString()).doesNotContain("fixture-private");}
}
